import {
  AlertCircle, ArrowLeft, ArrowRight, BarChart3, Bell, CalendarDays, Check, ChevronRight,
  CircleCheck, Clock3, FileCheck2, FileText, History, LayoutDashboard, ListChecks,
  LockKeyhole, Menu, Settings2, ShieldCheck, Sparkles, Upload, UserRound, UsersRound,
  X, SlidersHorizontal, Building2, ScrollText, Activity, Search, Plus, Eye, CheckCircle2,
} from 'lucide-react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { ErrorBoundary } from '@/components/error-boundary';
import { Toaster } from '@/components/ui/toaster';
import { TooltipProvider } from '@/components/ui/tooltip';
import NotFound from '@/pages/not-found';
import { Link, Route, Switch, useLocation, Router as WouterRouter } from 'wouter';
import { AdminRegulationsPage } from '@/components/admin-regulations';
import { createBusiness, getCurrentUser, getMyProfile, listAdminUsers, listBusinesses, loginAdmin, loginBusiness, registerApplicant, signupBusiness, setAdminToken, updateAdminUser, updateBusiness, updateMyProfile, getBusinessHome, getBusinessProfile, updateBusinessProfile, getBusinessRoadmap, listBusinessApplications, getBusinessApplication, getApplicationTimeline, createBusinessApplication, submitBusinessApplication, listBusinessActions, listBusinessCompliance, listBusinessRegulationChanges, listBusinessDocuments, uploadBusinessDocument, resolveBusinessAction, type Business, type BusinessApplication, type BusinessProfile, type User } from '@/lib/api';
