const queryClient = new QueryClient();
type Role = 'business' | 'department' | 'admin';
type AppStatus = 'Under Review' | 'Action Required' | 'Approved' | 'Inspection Scheduled';

type AppData = {
  applicationStatus: AppStatus;
  setApplicationStatus: (status: AppStatus) => void;
  querySent: boolean;
  setQuerySent: (value: boolean) => void;
  inspectionSlot: string;
  setInspectionSlot: (value: string) => void;
  toast: (message: string) => void;
};
const AuthContext = createContext<{ role: Role | null; user: User | null; ready: boolean; setSession: (user: User | null) => void }>({ role: null, user: null, ready: false, setSession: () => undefined });
const DataContext = createContext<AppData | null>(null);
const useAuth = () => useContext(AuthContext);
const useData = () => {
  const data = useContext(DataContext);
  if (!data) throw new Error('Paper Jam data context is missing');
  return data;
};

const businessNav = [
  ['Home', '/dashboard', LayoutDashboard], ['Approvals', '/approvals', ListChecks], ['Applications', '/applications', FileText], ['Compliance', '/compliance', ShieldCheck], ['Profile', '/profile', UserRound],
] as const;
const departmentNav = [
  ['Profile', '/officer/profile', UserRound],
] as const;
const adminNav = [
  ['Dashboard', '/admin', LayoutDashboard], ['Departments', '/admin/departments', Building2],
  ['Users', '/admin/users', UsersRound], ['Regulations', '/admin/regulations', ScrollText],
  ['Analytics', '/admin/bottlenecks', BarChart3], ['Audit', '/admin/audit', History], ['Settings', '/admin/settings', Settings2],
] as const;

function Logo() { return <Link href="/" className="brand" data-testid="link-logo">PAPER JAM</Link>; }

function Shell({ children, landing = false, role }: { children: ReactNode; landing?: boolean; role?: Role }) {
  const [location, setLocation] = useLocation();
  const { user, setSession } = useAuth();
  const nav = role === 'department' ? departmentNav : role === 'admin' ? adminNav : businessNav;
  return <div className="paper-app"><div className="shell">
    <header className="topbar">
      <div className="topbar__left"><Logo />
        {!landing && <nav className="pill-nav" aria-label="Primary navigation">{nav.map(([label, href, Icon]) =>
          <Link key={href} href={href} className={location === href ? 'active' : ''} data-testid={`link-nav-${label.toLowerCase().replaceAll(' ', '-')}`}><Icon size={13} />{label}</Link>)}</nav>}
        {landing && <nav className="pill-nav landing-links"><a href="#how-it-works">Home</a><a href="#businesses">For Businesses</a><a href="#departments">For Departments</a><a href="#admin">For Admin</a></nav>}
      </div>
      <div className="topbar__right">
        {landing ? <><Link href="/login" className="button button--light" data-testid="link-login">Log in</Link><Link href="/signup" className="button button--dark" data-testid="link-get-started">Get started <ArrowRight size={14} /></Link></> :
          <><Link href={role === 'business' ? '/new-application' : role === 'department' ? '/officer/profile' : '/admin'} className="button button--dark top-cta" data-testid="link-primary-cta">{role === 'business' ? <><Plus size={14} /> New application</> : role === 'department' ? <>My profile <ArrowRight size={14} /></> : <>Platform pulse <ArrowRight size={14} /></>}</Link><button className="button button--light tiny-button" aria-label="Notifications" onClick={() => setLocation('/actions')}><Bell size={14}/></button><Link href={role === 'admin' ? '/admin/profile' : role === 'department' ? '/officer/profile' : '/profile'} className="profile-chip" data-testid="link-profile-chip"><span className="avatar">{role === 'admin' ? 'PJ' : (user?.full_name || 'U').split(' ').map((part) => part[0]).slice(0, 2).join('').toUpperCase()}</span><span>{user?.full_name || 'Account'}</span></Link><button className="button button--light tiny-button" onClick={async () => { if (role === 'business') await apiRequest('/auth/business/logout', { method: 'POST' }).catch(() => undefined); setAdminToken(null); setSession(null); setLocation('/'); }} data-testid="button-logout">Sign out</button></>}
      </div>
    </header>
    {children}
    {!landing && <nav className="mobile-nav" aria-label="Mobile navigation">{nav.slice(0, 4).map(([label, href, Icon]) => <Link key={href} href={href} className={location === href ? 'active' : ''} data-testid={`mobile-nav-${label.toLowerCase().replaceAll(' ', '-')}`}><Icon size={17} />{label}</Link>)}</nav>}
  </div></div>;
}

function PageIntro({ eyebrow, title, copy, children }: { eyebrow?: string; title: string; copy?: string; children?: ReactNode }) {
  return <div className="page-intro">{eyebrow && <span className="eyebrow">{eyebrow}</span>}<h1 className="page-title">{title}</h1>{copy && <p>{copy}</p>}{children}</div>;
}
function Unauthorized() { return <Shell><main className="page center narrow-page"><div className="surface pad auth-message"><LockKeyhole size={27} /><span className="eyebrow">Permission required</span><h1 className="page-title">You don't have access to this area.</h1><p>This workspace is reserved for another Paper Jam role.</p><Link href="/" className="button button--dark" data-testid="link-return-home">Return Home <ArrowRight size={14} /></Link></div></main></Shell>; }
function RoleGate({ allowed, children }: { allowed: Role; children: ReactNode }) { return <RoleGateInner allowed={allowed}>{children}</RoleGateInner>; }
function RoleGateInner({ allowed, children }: { allowed: Role; children: ReactNode }) {
  const { role, ready } = useAuth(); const [, setLocation] = useLocation();
  useEffect(() => { if (ready && !role) setLocation('/login'); }, [ready, role, setLocation]);
  if (!ready) return <main className="page"><p className="muted-copy">Restoring your secure session?</p></main>;
  return role === allowed ? <>{children}</> : role ? <Unauthorized /> : null;
}

function Home() {
  const roles = [
    { id: 'business', anchor: 'businesses', title: 'For Businesses', headline: 'Create your business profile.', body: 'Keep your business identity and contact details in one place.', href: '/signup', action: 'Create an account', icon: FileText },
    { id: 'department', anchor: 'departments', title: 'For Departments', headline: 'A secure officer workspace.', body: 'Officer access is provisioned by an administrator.', href: '/login?role=department', action: 'Officer login', icon: ListChecks },
    { id: 'admin', anchor: 'admin', title: 'For Admin', headline: 'Manage regulatory knowledge.', body: 'Maintain source documents and manage account access.', href: '/login?role=admin', action: 'Admin login', icon: Activity },
  ];
  return <Shell landing><main className="page hero-page center" id="how-it-works">
    <span className="eyebrow">Approval intelligence, without the maze</span><h1 className="hero-title">Unjam Your<br />Approval Process.</h1>
    <p className="hero-copy">From discovering approvals to staying compliant,<br />Paper Jam brings the entire journey into one place.</p>
    <div className="hero-actions"><Link href="/signup" className="button button--dark" data-testid="link-start-application">Start your application <ArrowRight size={15} /></Link><a href="#businesses" className="button button--light" data-testid="link-explore">Explore how it works</a></div>
    <div className="hero-stage"><div className="hero-orbit"><span>business<br/>profile</span></div><div className="floating-card"><small>Applicant account</small><strong>Identity and contact details</strong></div><div className="floating-card"><small>Business profile</small><strong>Saved to your account</strong></div><div className="floating-card"><small>Regulatory knowledge</small><strong>Source-linked documents</strong></div><div className="floating-card"><small>Paper Jam / Phase 4</small><strong>Secure access for each role</strong></div></div>
    <section className="role-cards" id="businesses">{roles.map(({ id, anchor, title, headline, body, href, action, icon: Icon }) => <article className={`role-card role-card--${id}`} id={anchor} key={id}><div className="role-card__top"><span className="micro">{title}</span><Icon size={18} /></div><h2>{headline}</h2><p>{body}</p><Link href={href} className="button button--dark" data-testid={`link-role-${id}`}>{action} <ArrowRight size={14} /></Link></article>)}</section>
    <div className="feature-strip"><span>Discover</span><span>Prepare</span><span>Submit</span><span>Track</span><span>Comply</span></div>
  </main></Shell>;
}

function Login() {
  const [, setLocation] = useLocation(); const { setSession } = useAuth();
  const [email, setEmail] = useState(''); const [password, setPassword] = useState('');
  const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  const submit = async (event: FormEvent) => {
    event.preventDefault(); setBusy(true); setError('');
    try {
      const adminMode = ['admin', 'department'].includes(new URLSearchParams(window.location.search).get('role') || '');
      const result = adminMode ? await loginAdmin(email, password) : await loginBusiness(email, password); setAdminToken(result.access_token); setSession(result.user);
      setLocation(result.user.role === 'admin' ? '/admin' : result.user.role === 'officer' ? '/officer/profile' : '/dashboard');
    } catch (reason) { setAdminToken(null); setError(reason instanceof Error ? reason.message : 'Login failed.'); }
    finally { setBusy(false); }
  };
  return <Shell landing><main className="page auth-page"><section className="auth-copy"><span className="eyebrow">Paper Jam / Access</span><h1 className="page-title">Welcome back.</h1><p>Continue where you left off.</p><div className="soft-glow auth-glow"><span className="micro">One product, three clear journeys</span><div className="auth-journey"><span>Discover</span><ArrowRight size={14} /><span>Decide</span><ArrowRight size={14} /><span>Move forward</span></div></div></section><section className="surface pad auth-card"><span className="micro">Secure workspace</span><h2>Log in to Paper Jam</h2><form className="form-stack" onSubmit={submit}><div className="field"><label>Email</label><input required type="email" autoComplete="username" value={email} onChange={(event) => setEmail(event.target.value)} placeholder="you@company.com" data-testid="input-login-email" /></div><div className="field"><label>Password</label><input required type="password" autoComplete="current-password" value={password} onChange={(event) => setPassword(event.target.value)} placeholder="Enter your password" data-testid="input-login-password" /></div>{error && <p className="form-error" role="alert">{error}</p>}<button className="button button--dark" type="submit" disabled={busy} data-testid="button-login">{busy ? 'Signing in?' : 'Continue'} <ArrowRight size={14} /></button></form><div className="auth-foot">New to Paper Jam? <Link href="/signup" data-testid="link-create-account">Create an account</Link></div></section></main></Shell>;
}

function Signup() {
  const [, setLocation] = useLocation(); const { setSession } = useAuth();
  const [form, setForm] = useState({ name: '', business_name: '', email: '', phone: '', password: '', confirm: '' });
  const [error, setError] = useState(''); const [busy, setBusy] = useState(false);
  const update = (key: keyof typeof form) => (event: ChangeEvent<HTMLInputElement>) => setForm({ ...form, [key]: event.target.value });
  const submit = async (event: FormEvent) => {
    event.preventDefault(); setError('');
    if (form.password !== form.confirm) { setError('Passwords need to match.'); return; }
    setBusy(true);
    try {
      const result = await signupBusiness({ full_name: form.name, business_name: form.business_name, email: form.email, phone: form.phone, password: form.password }); setAdminToken(result.access_token); setSession(result.user); setLocation('/profile');
    } catch (reason) { setError(reason instanceof Error ? reason.message : 'Could not create your account.'); }
    finally { setBusy(false); }
  };
  return <Shell landing><main className="page auth-page signup-page"><section className="auth-copy"><span className="eyebrow">Paper Jam / Begin</span><h1 className="page-title">Create your Paper Jam account.</h1><p>Set up your account and start unjamming your approval process.</p><div className="passport mini-passport"><div className="passport__top"><span>Paper Jam / Passport</span><span>New</span></div><h3>{form.name || 'Your workspace'}.</h3><p>Discover ? Prepare ? Track</p></div></section><section className="surface pad auth-card"><span className="micro">Business account</span><h2>Your details</h2><form className="form-stack" onSubmit={submit}><div className="field"><label>Full name</label><input required autoComplete="name" value={form.name} onChange={update('name')} placeholder="Your name" data-testid="input-signup-name" /></div><div className="field"><label>Business name</label><input required value={form.business_name} onChange={update('business_name')} placeholder="Business name" /></div><div className="field"><label>Email</label><input required type="email" autoComplete="email" value={form.email} onChange={update('email')} placeholder="you@company.com" data-testid="input-signup-email" /></div><div className="field"><label>Phone</label><input required type="tel" autoComplete="tel" value={form.phone} onChange={update('phone')} placeholder="+91?" data-testid="input-signup-phone" /></div><div className="form-grid"><div className="field"><label>Password</label><input required minLength={8} type="password" autoComplete="new-password" value={form.password} onChange={update('password')} data-testid="input-signup-password" /></div><div className="field"><label>Confirm password</label><input required type="password" autoComplete="new-password" value={form.confirm} onChange={update('confirm')} data-testid="input-signup-confirm" /></div></div>{error && <p className="form-error" role="alert">{error}</p>}<button className="button button--dark" type="submit" disabled={busy} data-testid="button-create-account">{busy ? 'Creating account?' : 'Create account'} <ArrowRight size={14} /></button></form><div className="auth-foot">Already have an account? <Link href="/login" data-testid="link-login-existing">Log in</Link></div></section></main></Shell>;
}

function Dashboard() {
  const { user } = useAuth(); const [businesses, setBusinesses] = useState<Business[]>([]); const [selectedId, setSelectedId] = useState(''); const [loading, setLoading] = useState(true); const [error, setError] = useState(''); const [editing, setEditing] = useState(false); const [busy, setBusy] = useState(false);
  const selected = businesses.find((item) => item.id === selectedId) || businesses[0];
  const [form, setForm] = useState({ business_name: '', legal_name: '', business_type: '', industry: '', description: '', entity_type: '', registration_number: '', contact: { email: '', phone: '' }, address: { address_line_1: '', address_line_2: '', city: '', district: '', state: '', pincode: '', country: 'India' } });
  const load = async () => { setLoading(true); try { const result = await listBusinesses(); setBusinesses(result.items); setSelectedId((current) => result.items.some((item) => item.id === current) ? current : result.items[0]?.id || ''); } catch (reason) { setError(reason instanceof Error ? reason.message : 'Could not load businesses.'); } finally { setLoading(false); } };
  useEffect(() => { void load(); }, []);
  const beginEdit = () => { if (!selected) return; setForm({ business_name: selected.business_name, legal_name: selected.legal_name || '', business_type: selected.business_type, industry: selected.industry, description: selected.description || '', entity_type: selected.entity_type, registration_number: selected.registration_number || '', contact: { email: selected.contact.email || '', phone: selected.contact.phone || '' }, address: { address_line_1: selected.address.address_line_1, address_line_2: selected.address.address_line_2 || '', city: selected.address.city, district: selected.address.district, state: selected.address.state, pincode: selected.address.pincode, country: selected.address.country } }); setEditing(true); };
  const save = async (event: FormEvent) => { event.preventDefault(); if (!selected) return; setBusy(true); setError(''); try { await updateBusiness(selected.id, { ...form, contact: { email: form.contact.email || null, phone: form.contact.phone || null } }); await load(); setEditing(false); } catch (reason) { setError(reason instanceof Error ? reason.message : 'Could not update business.'); } finally { setBusy(false); } };
  return <RoleGate allowed="business"><Shell role="business"><main className="page"><PageIntro eyebrow="Applicant / Business profile" title={`Welcome, ${user?.full_name || 'applicant'}.`} copy="Your businesses are saved to your Paper Jam account."><Link className="button button--dark" href="/onboarding"><Plus size={14} /> Add a business</Link></PageIntro>{error && <p className="form-error" role="alert">{error}</p>}{loading ? <p className="muted-copy">Loading your businesses...</p> : businesses.length === 0 ? <section className="surface pad regulation-state"><Building2 size={25} /><h2>No business profiles yet</h2><p className="muted-copy">Create a business profile to continue.</p><Link className="button button--dark" href="/onboarding">Create business <ArrowRight size={14} /></Link></section> : <div className="layout"><section className="surface pad"><span className="micro">Your businesses</span><div className="list-stack">{businesses.map((business) => <button type="button" className={`journey-card ${selected?.id === business.id ? 'selected' : ''}`} key={business.id} onClick={() => { setSelectedId(business.id); setEditing(false); }}><div><h3>{business.business_name}</h3><p>{business.business_type} | {business.address.city}, {business.address.state}</p></div><span className="status">{business.status}</span></button>)}</div></section>{selected && <section className="surface pad"><div className="section-head"><div><span className="micro">Business profile</span><h2>{selected.business_name}</h2></div><button className="button button--light" onClick={beginEdit}>Edit profile</button></div>{editing ? <form className="form-stack" onSubmit={save}><div className="form-grid">{(['business_name','legal_name','business_type','industry','entity_type','registration_number'] as const).map((key) => <div className="field" key={key}><label>{key.replaceAll('_',' ')}</label><input required={['business_name','business_type','industry','entity_type'].includes(key)} value={form[key]} onChange={(event) => setForm({ ...form, [key]: event.target.value })} /></div>)}</div><div className="form-grid">{(['address_line_1','city','district','state','pincode'] as const).map((key) => <div className="field" key={key}><label>{key.replaceAll('_',' ')}</label><input required value={form.address[key]} onChange={(event) => setForm({ ...form, address: { ...form.address, [key]: event.target.value } })} /></div>)}</div><div className="row-actions"><button type="button" className="button button--light" onClick={() => setEditing(false)}>Cancel</button><button className="button button--dark" disabled={busy}>{busy ? 'Saving...' : 'Save profile'}</button></div></form> : <><p className="muted-copy">{selected.description || selected.business_type}</p><div className="form-grid"><div><span className="micro">Legal name</span><p>{selected.legal_name || 'Not provided'}</p></div><div><span className="micro">Industry</span><p>{selected.industry}</p></div><div><span className="micro">Entity type</span><p>{selected.entity_type}</p></div><div><span className="micro">Registration number</span><p>{selected.registration_number || 'Not provided'}</p></div><div><span className="micro">Address</span><p>{selected.address.address_line_1}, {selected.address.city}, {selected.address.district}, {selected.address.state} {selected.address.pincode}</p></div><div><span className="micro">Contact</span><p>{selected.contact.email || 'Not provided'} / {selected.contact.phone || 'Not provided'}</p></div></div><span className="status">{selected.status}</span></>}</section>}</div>}</main></Shell></RoleGate>;
}

function Onboarding() {
  const [, setLocation] = useLocation(); const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  const [form, setForm] = useState({ business_name: '', legal_name: '', business_type: '', industry: '', description: '', entity_type: '', registration_number: '', contact: { email: '', phone: '' }, address: { address_line_1: '', address_line_2: '', city: '', district: '', state: '', pincode: '', country: 'India' } });
  const submit = async (event: FormEvent) => { event.preventDefault(); setBusy(true); setError(''); try { await createBusiness({ ...form, contact: { email: form.contact.email || null, phone: form.contact.phone || null } }); setLocation('/dashboard'); } catch (reason) { setError(reason instanceof Error ? reason.message : 'Could not save business.'); } finally { setBusy(false); } };
  return <RoleGate allowed="business"><Shell role="business"><main className="page layout"><section><Link href="/dashboard" className="eyebrow"><ArrowLeft size={14} /> Business dashboard</Link><PageIntro eyebrow="Applicant / New business" title="Tell us about your business." copy="Create a profile for a business you own or are authorized to represent."/><form className="surface pad form-stack" onSubmit={submit}><div className="form-grid">{(['business_name','legal_name','business_type','industry','entity_type','registration_number'] as const).map((key) => <div className="field" key={key}><label>{key.replaceAll('_',' ')}</label><input required={['business_name','business_type','industry','entity_type'].includes(key)} value={form[key]} onChange={(event) => setForm({ ...form, [key]: event.target.value })} /></div>)}</div><div className="field"><label>Description</label><textarea rows={3} value={form.description} onChange={(event) => setForm({ ...form, description: event.target.value })} /></div><h3>Contact</h3><div className="form-grid"><div className="field"><label>Email</label><input type="email" value={form.contact.email} onChange={(event) => setForm({ ...form, contact: { ...form.contact, email: event.target.value } })} /></div><div className="field"><label>Phone</label><input type="tel" value={form.contact.phone} onChange={(event) => setForm({ ...form, contact: { ...form.contact, phone: event.target.value } })} /></div></div><h3>Business address</h3><div className="form-grid">{(['address_line_1','address_line_2','city','district','state','pincode','country'] as const).map((key) => <div className="field" key={key}><label>{key.replaceAll('_',' ')}</label><input required={key !== 'address_line_2'} value={form.address[key]} onChange={(event) => setForm({ ...form, address: { ...form.address, [key]: event.target.value } })} /></div>)}</div>{error && <p className="form-error" role="alert">{error}</p>}<button className="button button--dark" disabled={busy}>{busy ? 'Saving business...' : 'Save business profile'} <ArrowRight size={14} /></button></form></section></main></Shell></RoleGate>;
}

function BusinessHome() {
  const [data, setData] = useState<Awaited<ReturnType<typeof getBusinessHome>> | null>(null); const [error, setError] = useState('');
  useEffect(() => { void getBusinessHome().then(setData).catch((e) => setError(e instanceof Error ? e.message : 'Could not load workspace.')); }, []);
  return <RoleGate allowed="business"><Shell role="business"><main className="page"><PageIntro eyebrow="Business / Workspace" title={data?.business.display_name ? `Welcome, ${data.business.display_name}.` : 'Your business workspace.'} copy="Your applications, profile, and compliance information in one place." />{error && <p className="form-error" role="alert">{error}</p>}{!data ? <p className="muted-copy">Loading your workspace…</p> : <><section className="surface pad"><span className="micro">Your approval journey</span><h2>{data.roadmap.status === 'not_generated' ? 'Approval roadmap not generated' : data.roadmap.status}</h2><p className="muted-copy">{data.roadmap.message}</p><Link className="button button--light" href="/approvals">View roadmap <ArrowRight size={14}/></Link></section><div className="stats-grid" style={{ marginTop: '1rem' }}><Metric label="Applications" value={String(data.applications.total)} hint="created"/><Metric label="Active applications" value={String(data.applications.active)} hint="in progress"/><Metric label="Compliance items" value={String(data.compliance.total)} hint="from your records"/><Metric label="Profile complete" value={`${data.profile_completion.percentage}%`} hint={`${data.profile_completion.completed_fields} of ${data.profile_completion.required_fields} required fields`}/></div><div className="layout" style={{ marginTop: '1rem' }}><section className="surface pad"><span className="micro">Recent applications</span>{data.applications.items.length ? data.applications.items.map((item) => <ApplicationRow key={item.id} item={item}/>) : <p className="muted-copy">No applications yet. Start one when you’re ready.</p>}<Link className="button button--dark" href="/new-application"><Plus size={14}/> New application</Link></section><section className="surface pad"><span className="micro">Next step</span><h2>Complete your business profile</h2><p className="muted-copy">{data.profile_completion.missing_fields.length ? `Still needed: ${data.profile_completion.missing_fields.join(', ').replaceAll('_', ' ')}.` : 'Your required profile details are complete.'}</p><Link className="button button--light" href="/profile">Review profile <ArrowRight size={14}/></Link></section></div></>}</main></Shell></RoleGate>;
}

function ApplicationRow({ item }: { item: BusinessApplication }) { return <Link href={`/applications/${item.id}`} className="journey-card"><div><span className="micro">{item.approval_type}</span><h3>{item.approval_name}</h3><p>Current stage: {item.current_stage.replaceAll('_', ' ')}</p></div><span className="status">{item.status.replaceAll('_', ' ')}</span><ChevronRight size={16}/></Link>; }

function BusinessApprovals() { const [roadmap, setRoadmap] = useState<{status:string;message:string}|null>(null); useEffect(() => { void getBusinessRoadmap().then(setRoadmap); }, []); return <RoleGate allowed="business"><Shell role="business"><main className="page"><PageIntro eyebrow="Business / Discover" title="Your approval roadmap." copy="The roadmap will be generated after your business profile is evaluated."/><section className="surface pad regulation-state"><ListChecks size={25}/><h2>{roadmap?.status === 'not_generated' ? 'No roadmap has been generated' : 'Loading roadmap'}</h2><p className="muted-copy">{roadmap?.message || 'Loading…'}</p><Link className="button button--light" href="/profile">Complete business profile <ArrowRight size={14}/></Link></section></main></Shell></RoleGate>; }

function BusinessApplications() { const [items, setItems] = useState<BusinessApplication[]>([]); const [loading, setLoading] = useState(true); const [error, setError] = useState(''); useEffect(() => { void listBusinessApplications().then((x) => setItems(x.items)).catch((e) => setError(e.message)).finally(() => setLoading(false)); }, []); return <RoleGate allowed="business"><Shell role="business"><main className="page"><PageIntro eyebrow="Business / In motion" title="Your applications." copy="Every application and its current status from your business account."><Link href="/new-application" className="button button--dark"><Plus size={14}/> New application</Link></PageIntro>{error && <p className="form-error">{error}</p>}{loading ? <p className="muted-copy">Loading applications…</p> : items.length ? <div className="list-stack">{items.map((item) => <ApplicationRow key={item.id} item={item}/>)}</div> : <section className="surface pad regulation-state"><FileText size={25}/><h2>No applications yet</h2><p className="muted-copy">Applications you create will appear here.</p><Link href="/new-application" className="button button--dark">Start an application</Link></section>}</main></Shell></RoleGate>; }

function NewApplication() { const [name, setName] = useState(''); const [kind, setKind] = useState(''); const [created, setCreated] = useState<BusinessApplication|null>(null); const [error, setError] = useState(''); const [busy, setBusy] = useState(false); const submit = async (e: FormEvent) => { e.preventDefault(); setBusy(true); try { setCreated(await createBusinessApplication({approval_name:name, approval_type:kind})); } catch (x) { setError(x instanceof Error ? x.message : 'Could not create application.'); } finally { setBusy(false); } }; return <RoleGate allowed="business"><Shell role="business"><main className="page"><PageIntro eyebrow="Application / New" title="Start an application." copy="Enter the approval you want to apply for. This creates a draft; it does not submit or determine requirements."/>{created ? <section className="surface pad"><h2>Draft created</h2><ApplicationRow item={created}/><div className="row-actions"><Link className="button button--light" href={`/applications/${created.id}`}>View application</Link><button className="button button--dark" onClick={() => void submitBusinessApplication(created.id).then(setCreated).catch((x) => setError(x.message))}>Submit application</button></div></section> : <form className="surface pad form-stack" onSubmit={submit}><div className="field"><label>Approval name</label><input required maxLength={200} value={name} onChange={(e)=>setName(e.target.value)} placeholder="Enter the approval name"/></div><div className="field"><label>Approval type</label><input required maxLength={120} value={kind} onChange={(e)=>setKind(e.target.value)} placeholder="Enter the approval type"/></div>{error && <p className="form-error">{error}</p>}<button className="button button--dark" disabled={busy}>{busy?'Creating…':'Create draft'} <ArrowRight size={14}/></button></form>}</main></Shell></RoleGate>; }

function ApplicationTracking({ id }: { id: string }) { const [app, setApp] = useState<BusinessApplication|null>(null); const [timeline, setTimeline] = useState<Awaited<ReturnType<typeof getApplicationTimeline>>|null>(null); const [error,setError]=useState(''); useEffect(()=>{void Promise.all([getBusinessApplication(id),getApplicationTimeline(id)]).then(([a,t])=>{setApp(a);setTimeline(t)}).catch(e=>setError(e.message))},[id]); return <RoleGate allowed="business"><Shell role="business"><main className="page"><PageIntro eyebrow="Application / Tracking" title={app?.approval_name || 'Track your application.'} copy="Application events are shown from its recorded status."/>{error&&<p className="form-error">{error}</p>}{!timeline?<p className="muted-copy">Loading application…</p>:timeline.timeline.length===0?<section className="surface pad"><h2>Draft application</h2><p className="muted-copy">This application has not been submitted.</p></section>:<section className="surface pad"><div className="timeline">{timeline.timeline.map((item,index)=><div className="timeline-item" key={item.stage}><span className={`timeline-dot ${item.status==='completed'?'done':item.status==='current'?'active':''}`}>{item.status==='completed'?<Check size={13}/>:index+1}</span><div className="timeline-content"><h3>{item.stage.replaceAll('_',' ')}</h3><p>{item.completed_at?new Date(item.completed_at).toLocaleString():item.status}</p></div></div>)}</div></section>}</main></Shell></RoleGate>; }

function BusinessActionCard({ item }: { item: Record<string, unknown> }) { const [file,setFile]=useState<File|null>(null); const [notice,setNotice]=useState(''); const [error,setError]=useState(''); const [busy,setBusy]=useState(false); const send=async()=>{if(!file)return;setBusy(true);setError('');try{await uploadBusinessDocument(file,String(item.document_type||'requested_document'));await resolveBusinessAction(String(item.id));setNotice('Document uploaded and action resolved.')}catch(e){setError(e instanceof Error?e.message:'Could not upload document.')}finally{setBusy(false)}}; return <section className="surface pad"><span className="status">{String(item.status)}</span><p>{String(item.message||'')}</p><div className="metric-row"><span>Requested by</span><strong>{String(item.requested_by_department_name||'Not specified')}</strong></div><div className="metric-row"><span>Due</span><strong>{item.due_date?new Date(String(item.due_date)).toLocaleDateString():'Not specified'}</strong></div>{item.status==='open'&&<div className="row-actions"><input aria-label="Upload requested PDF" type="file" accept="application/pdf" onChange={e=>setFile(e.target.files?.[0]||null)}/><button className="button button--dark" disabled={!file||busy} onClick={()=>void send()}><Upload size={14}/>{busy?'Uploading…':'Upload updated document'}</button></div>}{error&&<p className="form-error">{error}</p>}{notice&&<p className="muted-copy" role="status">{notice}</p>}</section>; }
function BusinessActions() { const [items,setItems]=useState<Array<Record<string,unknown>>>([]); const [error,setError]=useState(''); useEffect(()=>{void listBusinessActions().then(x=>setItems(x.items)).catch(e=>setError(e.message))},[]); return <RoleGate allowed="business"><Shell role="business"><main className="page"><PageIntro eyebrow="Application / Action required" title="Action required." copy="Department requests associated with your applications."/>{error&&<p className="form-error">{error}</p>}{items.length?items.map(x=><BusinessActionCard key={String(x.id)} item={x}/>):<section className="surface pad regulation-state"><CheckCircle2 size={25}/><h2>No actions need your attention</h2><p className="muted-copy">Department requests will appear here when they are recorded.</p></section>}</main></Shell></RoleGate>; }

function BusinessCompliance() { const [counts,setCounts]=useState({items:0,changes:0,documents:0}); const [error,setError]=useState(''); useEffect(()=>{void Promise.all([listBusinessCompliance(),listBusinessRegulationChanges(),listBusinessDocuments()]).then(([a,b,c])=>setCounts({items:a.total,changes:b.total,documents:c.total})).catch(e=>setError(e.message))},[]); return <RoleGate allowed="business"><Shell role="business"><main className="page"><PageIntro eyebrow="After approval" title="Stay compliant." copy="Compliance records and regulation changes associated with your business."/>{error&&<p className="form-error">{error}</p>}<div className="stats-grid"><Metric label="Obligations" value={String(counts.items)} hint="recorded"/><Metric label="Regulation changes" value={String(counts.changes)} hint="affecting this business"/><Metric label="Documents" value={String(counts.documents)} hint="uploaded"/></div><section className="surface pad regulation-state" style={{marginTop:'1rem'}}><ShieldCheck size={25}/><h2>{counts.items ? `${counts.items} compliance records` : 'No compliance records yet'}</h2><p className="muted-copy">{counts.items ? 'Review your recorded obligations.' : 'Renewals and obligations appear here when created for your business.'}</p><Link className="button button--light" href="/compliance/guardian">Review regulation changes ({counts.changes})</Link></section></main></Shell></RoleGate>; }

function BusinessRegulationChanges() { const [items,setItems]=useState<Array<Record<string,unknown>>>([]); const [error,setError]=useState(''); useEffect(()=>{void listBusinessRegulationChanges().then(x=>setItems(x.items)).catch(e=>setError(e.message))},[]); return <RoleGate allowed="business"><Shell role="business"><main className="page"><PageIntro eyebrow="Compliance / Regulation changes" title="Something changed." copy="Regulation changes linked to your business profile."/>{error&&<p className="form-error">{error}</p>}{items.length?items.map(item=><section className="surface pad" key={String(item.id)}><span className="status">{String(item.status||'Review')}</span><h2>{String(item.title||item.name||'Regulation update')}</h2><div className="metric-row"><span>Effective</span><strong>{item.effective_date?new Date(String(item.effective_date)).toLocaleDateString():'Not specified'}</strong></div><p>{String(item.impact||item.summary||'')}</p><p className="muted-copy">{String(item.recommended_action||item.description||'Review the regulation details and required action.')}</p></section>):<section className="surface pad regulation-state"><Sparkles size={25}/><h2>No regulation changes recorded</h2><p className="muted-copy">Relevant changes will appear here when they are evaluated for your business.</p></section>}</main></Shell></RoleGate>; }

function BusinessProfile() { const [profile,setProfile]=useState<BusinessProfile|null>(null); const [error,setError]=useState(''); const [notice,setNotice]=useState(''); const [busy,setBusy]=useState(false); useEffect(()=>{void getBusinessProfile().then(setProfile).catch(e=>setError(e.message))},[]); const update=(key:keyof BusinessProfile,value:unknown)=>setProfile(p=>p?({...p,[key]:value}):p); const save=async(e:FormEvent)=>{e.preventDefault();if(!profile)return;setBusy(true);setError('');try{const updated=await updateBusinessProfile({legal_name:profile.legal_name,display_name:profile.display_name,business_type:profile.business_type,industry:profile.industry,entity_type:profile.entity_type,registration_number:profile.registration_number,pan:profile.pan,gstin:profile.gstin,email:profile.email,phone:profile.phone,registered_address:profile.registered_address,operating_address:profile.operating_address,contact_person:profile.contact_person,business_activities:profile.business_activities});setProfile(updated);setNotice('Business profile saved.')}catch(x){setError(x instanceof Error?x.message:'Could not save profile.')}finally{setBusy(false)}}; if(!profile)return <RoleGate allowed="business"><Shell role="business"><main className="page"><PageIntro eyebrow="Business / Profile" title="Your business profile."/>{error?<p className="form-error">{error}</p>:<p className="muted-copy">Loading profile…</p>}</main></Shell></RoleGate>; const text=(key:keyof BusinessProfile,label:string)=><div className="field" key={key}><label>{label}</label><input value={String(profile[key]??'')} onChange={e=>update(key,e.target.value)}/></div>; return <RoleGate allowed="business"><Shell role="business"><main className="page"><PageIntro eyebrow="Business / Profile" title={profile.display_name||'Your business profile.'} copy="Edit the structured business details used by future approval workflows."/><form className="surface pad form-stack" onSubmit={save}><div className="form-grid">{text('display_name','Business name')}{text('legal_name','Legal name')}{text('business_type','Business type')}{text('industry','Industry')}{text('entity_type','Entity type')}{text('registration_number','Registration number')}{text('pan','PAN')}{text('gstin','GSTIN')}{text('email','Email')}{text('phone','Phone')}</div><h3>Registered address</h3><div className="form-grid">{(['address_line_1','address_line_2','city','district','state','pincode','country'] as const).map(k=><div className="field" key={k}><label>{k.replaceAll('_',' ')}</label><input value={profile.registered_address?.[k]||''} onChange={e=>update('registered_address',{...profile.registered_address,[k]:e.target.value})}/></div>)}</div><h3>Operating address</h3><div className="form-grid">{(['address_line_1','address_line_2','city','district','state','pincode','country'] as const).map(k=><div className="field" key={k}><label>{k.replaceAll('_',' ')}</label><input value={profile.operating_address?.[k]||''} onChange={e=>update('operating_address',{...profile.operating_address,[k]:e.target.value})}/></div>)}</div><div className="field"><label>Business activities (one per line)</label><textarea rows={3} value={(profile.business_activities||[]).join('\n')} onChange={e=>update('business_activities',e.target.value.split('\n').map(x=>x.trim()).filter(Boolean))}/></div><div className="field"><label>Contact person</label><input value={profile.contact_person?.name||''} onChange={e=>update('contact_person',{...profile.contact_person,name:e.target.value})}/></div>{profile.completion&&<p className="muted-copy">Profile completion: {profile.completion.percentage}% · Missing: {profile.completion.missing_fields.join(', ')||'none'}</p>}{error&&<p className="form-error">{error}</p>}{notice&&<p className="muted-copy" role="status">{notice}</p>}<button className="button button--dark" disabled={busy}>{busy?'Saving…':'Save business profile'} <ArrowRight size={14}/></button></form></main></Shell></RoleGate>; }

function Profile({ role }: { role: Role }) {
  const { user, setSession } = useAuth(); const [name, setName] = useState(''); const [phone, setPhone] = useState(''); const [notice, setNotice] = useState(''); const [error, setError] = useState(''); const [busy, setBusy] = useState(false);
  useEffect(() => { void getMyProfile().then((profile) => { setName(profile.full_name); setPhone(profile.phone || ''); }).catch((reason) => setError(reason instanceof Error ? reason.message : 'Could not load profile.')); }, []);
  const save = async (event: FormEvent) => { event.preventDefault(); setBusy(true); setError(''); try { const updated = await updateMyProfile({ full_name: name, phone }); setSession(updated); setNotice('Profile updated.'); } catch (reason) { setError(reason instanceof Error ? reason.message : 'Could not update profile.'); } finally { setBusy(false); } };
  return <RoleGate allowed={role}><Shell role={role}><main className="page"><PageIntro eyebrow={`${role} / Account`} title="Your profile." copy="Update the account information attached to your Paper Jam session."/><form className="surface pad form-stack" onSubmit={save}><div className="field"><label>Full name</label><input required value={name} onChange={(event) => setName(event.target.value)} /></div><div className="field"><label>Email</label><input readOnly value={user?.email || ''} /></div><div className="field"><label>Phone</label><input value={phone} onChange={(event) => setPhone(event.target.value)} /></div><div className="field"><label>Role</label><input readOnly value={user?.role || ''} /></div>{error && <p className="form-error" role="alert">{error}</p>}{notice && <p className="muted-copy" role="status">{notice}</p>}<button className="button button--dark" disabled={busy}>{busy ? 'Saving...' : 'Save profile'}</button></form></main></Shell></RoleGate>;
}

function Phase5Placeholder({ role }: { role: Role }) { return <RoleGate allowed={role}><Shell role={role}><main className="page"><PageIntro eyebrow="Paper Jam / Phase 4" title="Your account is ready." copy="Approval workflows will appear here in a later phase. Your identity and business profiles are available now."/><Link className="button button--dark" href={role === 'business' ? '/dashboard' : role === 'department' ? '/officer/profile' : '/admin'}>Return to profile <ArrowRight size={14}/></Link></main></Shell></RoleGate>; }

function AdminShellPage({ children, title, eyebrow, copy, action }: { children: ReactNode; title: string; eyebrow: string; copy: string; action?: ReactNode }) { return <RoleGate allowed="admin"><Shell role="admin"><main className="page"><PageIntro eyebrow={eyebrow} title={title} copy={copy}>{action}</PageIntro>{children}</main></Shell></RoleGate>; }
function AdminOverview() {
  const [metrics, setMetrics] = useState<{ active_regulations: number; regulation_versions: number; pending_rag_queries: number } | null>(null); const [businessCount, setBusinessCount] = useState<number | null>(null); const [error, setError] = useState('');
  useEffect(() => { void Promise.all([apiRequest<typeof metrics>('/admin/regulations/metrics'), listBusinesses()]).then(([reg, businesses]) => { setMetrics(reg); setBusinessCount(businesses.total); }).catch((reason) => setError(reason instanceof Error ? reason.message : 'Could not load admin data.')); }, []);
  return <AdminShellPage eyebrow="Platform / Overview" title="Paper Jam overview." copy="Live account and regulatory knowledge totals from the database."><div className="stats-grid"><Metric label="Business profiles" value={businessCount === null ? '?' : String(businessCount)} hint="in the database" /><Metric label="Active regulations" value={metrics ? String(metrics.active_regulations) : '?'} hint="current knowledge" /><Metric label="Regulation versions" value={metrics ? String(metrics.regulation_versions) : '?'} hint="processed documents" /><Metric label="Pending RAG queries" value={metrics ? String(metrics.pending_rag_queries) : '?'} hint="awaiting answer" /></div>{error && <p className="form-error" role="alert">{error}</p>}<section className="surface pad" style={{ marginTop: '1rem' }}><span className="micro">Regulatory knowledge</span><h2>Live from the database.</h2><p className="muted-copy">Manage uploaded rules, guidance, and searchable source documents.</p><Link href="/admin/regulations" className="button button--dark">Manage regulations <ArrowRight size={14}/></Link></section></AdminShellPage>;
}
function Metric({ label, value, hint, danger = false }: { label: string; value: string; hint: string; danger?: boolean }) { return <div className="surface stat"><span className="micro">{label}</span><h3>{value}</h3><p>{danger ? <span className="status status--red">{hint}</span> : hint}</p></div>; }
function AdminDepartments() { return <AdminShellPage eyebrow="Admin / Network" title="Departments" copy="Officer identities can be associated with a department when those records are available."><section className="surface pad regulation-state"><Building2 size={25}/><h2>No department directory is configured</h2><p className="muted-copy">Department workflows are outside Phase 4. Officer accounts and department IDs can be managed from Users.</p><Link className="button button--dark" href="/admin/users">Manage users</Link></section></AdminShellPage>; }
function AdminUsers() {
  const [users, setUsers] = useState<User[]>([]); const [filter, setFilter] = useState('All'); const [error, setError] = useState(''); const [loading, setLoading] = useState(true); const [busyId, setBusyId] = useState('');
  const load = async () => { setLoading(true); try { const result = await listAdminUsers(); setUsers(result.items); setError(''); } catch (reason) { setError(reason instanceof Error ? reason.message : 'Could not load users.'); } finally { setLoading(false); } };
  useEffect(() => { void load(); }, []);
  const visible = filter === 'All' ? users : users.filter((user) => user.role === filter.toLowerCase());
  const change = async (user: User, patch: { role?: User['role']; status?: 'active' | 'inactive' }) => { setBusyId(user.id); setError(''); try { await updateAdminUser(user.id, patch); await load(); } catch (reason) { setError(reason instanceof Error ? reason.message : 'Could not update user.'); } finally { setBusyId(''); } };
  return <AdminShellPage eyebrow="Admin / People" title="People using Paper Jam." copy="Manage real applicant and officer accounts stored in the users collection."><div className="tabs admin-tabs">{['All','Applicant','Officer','Admin'].map((item) => <button className={`tab ${filter === item ? 'active' : ''}`} key={item} onClick={() => setFilter(item)}>{item}</button>)}</div>{error && <p className="form-error" role="alert">{error}</p>}{loading ? <p className="muted-copy">Loading users?</p> : visible.length === 0 ? <section className="surface pad regulation-state"><UsersRound size={25}/><h2>No users found</h2><p className="muted-copy">Accounts appear here after an applicant registers or an officer account is created.</p></section> : <div className="admin-user-grid">{visible.map((user) => <article className="surface pad user-card" key={user.id}><div className="user-card__top"><div className="avatar">{user.full_name.split(' ').map((part) => part[0]).slice(0,2).join('').toUpperCase()}</div><span className={`status ${user.status === 'active' ? 'status--green' : 'status--amber'}`}>{user.status}</span></div><h2>{user.full_name}</h2><p className="muted-copy">{user.email} ? {user.role}</p><div className="metric-row"><span>Phone</span><strong>{user.phone || 'Not provided'}</strong></div><div className="metric-row"><span>Last login</span><strong>{user.last_login_at ? new Date(user.last_login_at).toLocaleDateString() : 'Never'}</strong></div><div className="field"><label>Role</label><select aria-label={`Role for ${user.full_name}`} value={user.role} disabled={busyId === user.id} onChange={(event) => void change(user, { role: event.target.value as User['role'] })}><option value="applicant">Applicant</option><option value="officer">Officer</option><option value="admin">Admin</option></select></div><div className="row-actions"><button className={`button ${user.status === 'active' ? 'button--danger' : 'button--soft'} tiny-button`} disabled={busyId === user.id} onClick={() => void change(user, { status: user.status === 'active' ? 'inactive' : 'active' })}>{user.status === 'active' ? 'Deactivate' : 'Activate'}</button></div></article>)}</div>}</AdminShellPage>;
}
function AdminRegulations() { return <AdminRegulationsPage>{(content, openUpload) => <AdminShellPage eyebrow="Admin / Knowledge" title="Regulatory knowledge." copy="Manage the rules that power approval decisions." action={<button className="button button--dark" onClick={openUpload} data-testid="button-upload-regulation"><Upload size={14} /> Upload new version</button>}>{content}</AdminShellPage>}</AdminRegulationsPage>; }
function AdminRegulationChange() { return <Phase5Placeholder role="admin"/>; }
function AdminBottlenecks() { return <Phase5Placeholder role="admin"/>; }
function AdminAudit() {
  const [events, setEvents] = useState<Array<{ id: string; action: string; actor_user_id?: string; target_type?: string; timestamp: string }>>([]); const [error, setError] = useState('');
  useEffect(() => { void apiRequest<{items: typeof events}>('/admin/audit').then((result) => setEvents(result.items)).catch((reason) => setError(reason instanceof Error ? reason.message : 'Could not load audit events.')); }, []);
  return <AdminShellPage eyebrow="Admin / Accountability" title="Everything has a history." copy="Phase 4 account and business events recorded in the audit log.">{error && <p className="form-error" role="alert">{error}</p>}<section className="surface pad"><div className="timeline">{events.length ? events.map((event, index) => <div className="timeline-item" key={event.id}><span className={`timeline-dot ${index === 0 ? 'active' : 'done'}`}>{index === 0 ? <History size={13}/> : <Check size={13}/>}</span><div className="timeline-content"><h3>{event.action.replaceAll('_',' ').toLowerCase()}</h3><p>{new Date(event.timestamp).toLocaleString()}</p><span className="micro">{event.target_type || 'account'} ? {event.target_type === 'business' ? 'business record' : 'user record'}</span></div></div>) : <p className="muted-copy">No audit events recorded yet.</p>}</div></section></AdminShellPage>;
}
function AdminSettings() { return <AdminShellPage eyebrow="Admin / Control room" title="System settings." copy="System-wide configuration is managed outside the Phase 4 account and business profile workflows."><section className="surface pad"><span className="micro">Configuration</span><h2>No editable settings are available here yet.</h2><p className="muted-copy">Regulatory documents and account roles can be managed from their respective admin sections.</p></section></AdminShellPage>; }

function Router() { return <Switch><Route path="/" component={Home} /><Route path="/login" component={Login} /><Route path="/signup" component={Signup} /><Route path="/onboarding" component={Onboarding} /><Route path="/dashboard" component={BusinessHome} /><Route path="/approvals" component={BusinessApprovals} /><Route path="/applications/:id">{(params) => <ApplicationTracking id={params.id}/>}</Route><Route path="/applications" component={BusinessApplications} /><Route path="/new-application" component={NewApplication} /><Route path="/actions" component={BusinessActions} /><Route path="/compliance/guardian" component={BusinessRegulationChanges} /><Route path="/compliance" component={BusinessCompliance} /><Route path="/profile" component={BusinessProfile} /><Route path="/officer" component={() => <Phase5Placeholder role="department"/>} /><Route path="/officer/profile" component={() => <Profile role="department" />} /><Route path="/officer/:rest*" component={() => <Phase5Placeholder role="department"/>} /><Route path="/admin" component={AdminOverview} /><Route path="/admin/departments" component={AdminDepartments} /><Route path="/admin/users" component={AdminUsers} /><Route path="/admin/regulations" component={AdminRegulations} /><Route path="/admin/regulation-change" component={AdminRegulationChange} /><Route path="/admin/bottlenecks" component={AdminBottlenecks} /><Route path="/admin/audit" component={AdminAudit} /><Route path="/admin/settings" component={AdminSettings} /><Route path="/admin/profile" component={() => <Profile role="admin" />} /><Route path="/:rest*" component={() => <Phase5Placeholder role="business"/>} /><Route component={NotFound} /></Switch>; }
function RoutedErrorBoundary({ children }: { children: ReactNode }) { const [location] = useLocation(); return <ErrorBoundary resetKey={location}>{children}</ErrorBoundary>; }
function App() {
  const [user, setUser] = useState<User | null>(null); const [ready, setReady] = useState(false);
  const setSession = (nextUser: User | null) => { setUser(nextUser); if (!nextUser) setAdminToken(null); };
  const role: Role | null = ['applicant', 'business_owner', 'business_admin', 'business_user'].includes(user?.role || '') ? 'business' : user?.role === 'officer' ? 'department' : user?.role === 'admin' ? 'admin' : null;
  useEffect(() => { const clearSession = () => setUser(null); window.addEventListener('paperjam:unauthorized', clearSession); return () => window.removeEventListener('paperjam:unauthorized', clearSession); }, []);
  useEffect(() => { let mounted = true; if (!localStorage.getItem('paperjam_access_token') && !localStorage.getItem('paperjam_admin_token')) { setReady(true); return; } void getCurrentUser().then((current) => { if (mounted) setUser(current); }).catch(() => { setAdminToken(null); }).finally(() => { if (mounted) setReady(true); }); return () => { mounted = false; }; }, []);
  const [applicationStatus, setApplicationStatus] = useState<AppStatus>('Under Review'); const [querySent, setQuerySent] = useState(false); const [inspectionSlot, setInspectionSlot] = useState(''); const [notice, setNotice] = useState(''); const toast = (message: string) => { setNotice(message); window.setTimeout(() => setNotice(''), 3200); }; const data = { applicationStatus, setApplicationStatus, querySent, setQuerySent, inspectionSlot, setInspectionSlot, toast };
  return <QueryClientProvider client={queryClient}><TooltipProvider><AuthContext.Provider value={{ role, user, ready, setSession }}><DataContext.Provider value={data}><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><RoutedErrorBoundary><Router /></RoutedErrorBoundary></WouterRouter>{notice && <div className="toast-note" role="status" data-testid="toast-notice">{notice}</div>}</DataContext.Provider></AuthContext.Provider></TooltipProvider><Toaster /></QueryClientProvider>;
}
export default App;
